// The sample data covers 2026-07-29 to 2026-09-28. Each real day replays the next sample day, looping.
const first = Date.UTC(2026, 6, 29);
const daysSince = Math.floor((Date.now() - Date.UTC(2026, 10, 1)) / 86400000);
const offset = ((daysSince % 62) + 62) % 62;
return [{ json: { date: new Date(first + offset * 86400000).toISOString().slice(0, 10) } }];

// ===== ANALYST-OWNED LOGIC =====
// This is the only file you should need to edit. The code does the legwork; you own the meaning.
// KPI tree, what counts as normal, the business calendar, data-check tolerances and the context
// the write-up is allowed to cite all live here.

const LOGIC = {
  // KPIs the agent watches every day. Primary first; secondary are the levers underneath.
  kpis: {
    primary: ['gmv'],
    secondary: ['orders', 'aov', 'sessions', 'conversion']
  },

  // How the KPIs break down. Every parent must equal the product of its children,
  // and the calculation check proves it every run. If you edit this, the check tells you
  // when a definition doesn't add up.
  kpi_tree: {
    gmv: ['orders', 'aov'],                           // GMV = orders x average order value
    orders: ['sessions', 'conversion'],               // orders = sessions x conversion
    conversion: ['checkout_rate', 'checkout_completion'], // conversion = checkout rate x share of checkouts that become orders
    aov: ['items_per_order', 'price_per_item']        // AOV = items per order x price per item
  },

  // What counts as a real move (per scope): at least this % change AND at least Z_MIN robust
  // standard deviations away from the same weekday over the previous BASELINE_WEEKS weeks.
  baseline_weeks: 4,
  thresholds: { total: 0.05, city: 0.08, store: 0.15 },
  z_min: 3,
  noise_floor: { total: 0.015, city: 0.025, store: 0.04 }, // minimum noise assumed, so quiet weeks don't make tiny moves look huge

  // Splits the agent drills into when something moves.
  splits: ['user_type', 'payment', 'city', 'store', 'category'],

  // Known events: the numbers are expected to break, so no alert.
  calendar: [
    { date: '2026-09-23', name: 'ZipBasket Anniversary Sale (planned, all cities)' }
  ],

  // Data checks run before any analysis. A store that fails one is set aside for the day
  // (and from the comparison weeks), and the email reports a data problem instead of a business cause.
  data_checks: {
    last_event_hour_min: 22,        // data for a day should run until at least 10 PM
    cross_table_tolerance: 0.02,    // items in the orders table vs the category table may differ by 2% at most
    max_stores_set_aside: 0.25      // if more than 25% of stores fail, don't analyse at all today
  },

  // Business context the write-up may cite. Tags decide when a note is relevant.
  // Fictional, for the ZipBasket demo: replace with what you know about your business.
  context: [
    { tags: ['upi_success', 'payment'], note: 'All UPI payments go through one payment gateway partner. A city-level UPI drop usually means a gateway or bank issue, not an app release.' },
    { tags: ['dairy'], note: 'Dairy is restocked twice a day by one supplier per city. More than 6 out-of-stock hours means a missed delivery.' },
    { tags: ['user_type'], note: 'Growth runs new-user campaigns without telling analytics. If the new-user share jumps, ask the growth team first.' }
  ]
};


// ===== Sample data generator (replace generate() with a query on your own warehouse) =====
// ZipBasket (fictional 10-minute grocery app): deterministic sample data with planted incidents.
// Pure JS, no dependencies, so the same code runs inside an n8n Code node.

function makeRng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const START = '2026-07-01';
const DAYS = 90;
const CITIES = {
  Bengaluru: { base: 4200, stores: ['Koramangala', 'Indiranagar', 'HSR Layout', 'Whitefield', 'Jayanagar'] },
  Delhi: { base: 4000, stores: ['Saket', 'Dwarka', 'Rohini', 'Lajpat Nagar', 'Karol Bagh'] },
  Mumbai: { base: 3800, stores: ['Andheri', 'Bandra', 'Powai', 'Thane', 'Dadar'] },
  Hyderabad: { base: 3000, stores: ['Gachibowli', 'Madhapur', 'Kondapur', 'Banjara Hills', 'Kukatpally'] }
};
const WEEKDAY = [1.15, 0.92, 0.90, 0.93, 0.95, 1.05, 1.18]; // Sun..Sat
const USERS = {
  new: { share: 0.15, checkout: 0.115, items: 3.6 },
  repeat: { share: 0.85, checkout: 0.17, items: 5.4 }
};
const PAYMENTS = { UPI: { share: 0.70, success: 0.94 }, Card: { share: 0.15, success: 0.92 }, COD: { share: 0.15, success: 0.99 } };
const CATEGORIES = {
  dairy: { share: 0.22, price: 55 }, fruits_veg: { share: 0.25, price: 60 }, snacks: { share: 0.18, price: 90 },
  beverages: { share: 0.12, price: 85 }, staples: { share: 0.15, price: 110 }, personal_care: { share: 0.08, price: 150 }
};
const NEW_USER_PRICE_FACTOR = 0.92; // new users buy slightly cheaper baskets

// Business calendar the agent is told about (known events are not alerts).
const CALENDAR = [{ day: 84, name: 'ZipBasket Anniversary Sale (planned, all cities)' }];

// Planted incidents (the agent is NOT told about these).
const INCIDENTS = [
  { id: 'upi_failure', days: [61, 62], city: 'Bengaluru', note: 'UPI success rate collapses in Bengaluru; some users retry with card' },
  { id: 'dairy_stockout', days: [70, 71], city: 'Delhi', stores: ['Saket', 'Dwarka', 'Rohini'], note: 'Dairy out of stock most of the day in 3 Delhi stores' },
  { id: 'new_user_campaign', days: [78, 79, 80], note: 'Acquisition campaign triples new-user traffic; every segment behaves normally (mix shift)' },
  { id: 'anniversary_sale', days: [84], note: 'Planned sale, in the business calendar; should not alert' }
];

// Planted DATA problems (pipeline faults, not business events). The agent should call these data problems.
const DATA_INCIDENTS = [
  { id: 'store_stops_reporting', day: 66, store: 'Powai', last_hour: 13, share_of_day: 0.45, note: 'Powai data stops at 1 PM; only 45% of the day arrives' },
  { id: 'duplicate_load', day: 75, store: 'Gachibowli', note: 'Gachibowli rows loaded twice' }
];

function dateOf(d) {
  const t = new Date(START + 'T00:00:00Z');
  t.setUTCDate(t.getUTCDate() + d);
  return t.toISOString().slice(0, 10);
}

function generate(seed) {
  const rnd = makeRng(seed || 42);
  const noise = sd => { let s = 0; for (let i = 0; i < 6; i++) s += rnd(); return Math.exp((s - 3) * Math.sqrt(2) * sd); };
  const funnel = [];   // date, city, store, user_type: sessions, checkouts
  const orders = [];   // date, city, store, user_type, payment: checkouts, orders, gmv, items
  const cats = [];     // date, city, store, category: items, gmv, stockout_hours
  const storeFactor = {};
  for (const [city, c] of Object.entries(CITIES)) c.stores.forEach(s => { storeFactor[s] = 0.8 + 0.4 * rnd(); });

  for (let d = 0; d < DAYS; d++) {
    const date = dateOf(d);
    const wd = new Date(date + 'T00:00:00Z').getUTCDay();
    const trend = 1 + 0.0015 * d;
    const sale = d === 84;
    const campaign = [78, 79, 80].includes(d);
    for (const [city, c] of Object.entries(CITIES)) {
      for (const store of c.stores) {
        const storeSessions = c.base * storeFactor[store] * WEEKDAY[wd] * trend * noise(0.022) * (sale ? 1.7 : 1);
        const stockout = INCIDENTS[1].days.includes(d) && city === 'Delhi' && INCIDENTS[1].stores.includes(store);
        const upiDown = INCIDENTS[0].days.includes(d) && city === 'Bengaluru';
        const catItems = {};
        for (const [ut, u] of Object.entries(USERS)) {
          const sessions = Math.round(storeSessions * u.share * (campaign && ut === 'new' ? 3.2 : 1) * noise(0.012));
          const checkoutRate = u.checkout * noise(0.012) * (sale ? 1.1 : 1) * (stockout ? 0.94 : 1);
          const checkouts = Math.round(sessions * checkoutRate);
          funnel.push({ date, city, store, user_type: ut, sessions, checkouts, last_event_hour: 23 });
          let retryToCard = 0;
          for (const [pm, p] of Object.entries(PAYMENTS)) {
            let pmCheckouts = Math.round(checkouts * p.share * noise(0.008));
            let success = p.success * noise(0.006);
            if (pm === 'UPI' && upiDown) { success = 0.52 * noise(0.03); retryToCard = Math.round(pmCheckouts * (1 - success) * 0.35); }
            if (pm === 'Card') pmCheckouts += retryToCard;
            const ords = Math.min(pmCheckouts, Math.round(pmCheckouts * Math.min(success, 0.995)));
            const itemsPerOrder = u.items * noise(0.012) * (stockout ? 0.80 : 1);
            const rawItems = ords * itemsPerOrder;
            let gmv = 0, shareSum = 0;
            for (const [cat, cc] of Object.entries(CATEGORIES)) {
              let share = cc.share;
              if (stockout) share = cat === 'dairy' ? cc.share * 0.12 : cc.share * (1 + (0.22 * 0.88 * 0.3) / 0.78);
              shareSum += share;
              const ci = Math.round(rawItems) * share;
              const cg = ci * cc.price * (ut === 'new' ? NEW_USER_PRICE_FACTOR : 1) * noise(0.01);
              catItems[cat] = catItems[cat] || { items: 0, gmv: 0 };
              catItems[cat].items += ci; catItems[cat].gmv += cg; gmv += cg;
            }
            // Items in the orders table = items across categories (on stockout days the lost dairy items are gone from both).
            const items = Math.round(Math.round(rawItems) * shareSum);
            orders.push({ date, city, store, user_type: ut, payment: pm, checkouts: pmCheckouts, orders: ords, gmv: Math.round(gmv), items });
          }
        }
        for (const [cat, v] of Object.entries(catItems)) {
          const so = stockout && cat === 'dairy' ? 14 + Math.round(rnd() * 4) : (rnd() < 0.03 ? 1 + Math.round(rnd() * 2) : 0);
          cats.push({ date, city, store, category: cat, items: Math.round(v.items), gmv: Math.round(v.gmv), stockout_hours: so });
        }
      }
    }
  }
  // Data problems are applied after the business data, so every other number stays the same.
  for (const di of DATA_INCIDENTS) {
    const date = dateOf(di.day), hit = r => r.date === date && r.store === di.store;
    if (di.id === 'store_stops_reporting') {
      const cut = r => { ['sessions', 'checkouts', 'orders', 'gmv', 'items'].forEach(k => { if (k in r) r[k] = Math.round(r[k] * di.share_of_day); }); };
      funnel.filter(hit).forEach(r => { cut(r); r.last_event_hour = di.last_hour; });
      orders.filter(hit).forEach(cut);
      cats.filter(hit).forEach(cut);
    }
    if (di.id === 'duplicate_load') {
      [funnel, orders, cats].forEach(t => t.filter(hit).forEach(r => t.push(Object.assign({}, r))));
    }
  }
  return { start: START, days: DAYS, funnel, orders, cats, calendar: CALENDAR.map(e => ({ date: dateOf(e.day), name: e.name })) };
}


// ===== Data checks and calculation checks (no AI) =====
// Sanity checks. Two kinds:
// 1. Data checks, on the raw pull, before any analysis: is the data complete and believable?
// 2. Calculation checks, after the analysis: do the numbers add back up?
// No AI, no dependencies.

const NUMERIC = ['sessions', 'checkouts', 'orders', 'gmv', 'items', 'stockout_hours'];

// Data checks for one date. Returns a list of issues: { date, store, check, detail, numbers }.
function dataChecks(day, date, masterStores, cfg) {
  const issues = [];
  const add = (store, check, detail) => issues.push({ date, store, check, detail });
  if (!day || !day.funnel.length) { add('*', 'missing_day', `No data at all for ${date}.`); return issues; }

  // 1. Every store reported, in every table.
  for (const [table, rows] of Object.entries({ funnel: day.funnel, orders: day.orders, categories: day.cats })) {
    const seen = new Set(rows.map(r => r.store));
    masterStores.forEach(s => { if (!seen.has(s)) add(s, 'store_missing', `${s} has no rows in the ${table} table.`); });
  }

  // 2. No duplicate rows (a pipeline that loaded the same data twice).
  const keys = { funnel: r => r.store + '|' + r.user_type, orders: r => r.store + '|' + r.user_type + '|' + r.payment, categories: r => r.store + '|' + r.category };
  for (const [table, rows] of Object.entries({ funnel: day.funnel, orders: day.orders, categories: day.cats })) {
    const count = {};
    rows.forEach(r => { const k = keys[table](r); count[k] = (count[k] || 0) + 1; });
    const dupStores = {};
    Object.entries(count).forEach(([k, n]) => { if (n > 1) { const s = k.split('|')[0]; dupStores[s] = (dupStores[s] || 0) + n - 1; } });
    Object.entries(dupStores).forEach(([s, n]) => add(s, 'duplicate_rows', `${s} has ${n} duplicate rows in the ${table} table (the same data loaded twice).`));
  }

  // 3. No impossible values.
  const bad = {};
  const flag = (s, why) => { (bad[s] = bad[s] || new Set()).add(why); };
  [...day.funnel, ...day.orders, ...day.cats].forEach(r => NUMERIC.forEach(k => { if (k in r && !(r[k] >= 0)) flag(r.store, `negative or missing ${k}`); }));
  day.funnel.forEach(r => { if (r.checkouts > r.sessions) flag(r.store, 'more checkouts than sessions'); });
  day.orders.forEach(r => {
    if (r.orders > r.checkouts) flag(r.store, 'more orders than payment attempts');
    if (r.orders > 0 && !(r.gmv > 0)) flag(r.store, 'orders with no GMV');
    if (r.items < r.orders) flag(r.store, 'fewer items than orders');
  });
  Object.entries(bad).forEach(([s, why]) => add(s, 'impossible_values', `${s} has impossible values: ${[...why].join(', ')}.`));

  // 4. Data runs to the end of the day (a pipeline that stopped mid-day looks like a business crash).
  if (day.funnel.some(r => 'last_event_hour' in r)) {
    const last = {};
    day.funnel.forEach(r => { last[r.store] = Math.max(last[r.store] == null ? -1 : last[r.store], r.last_event_hour); });
    Object.entries(last).forEach(([s, h]) => { if (h < cfg.last_event_hour_min) add(s, 'data_stops_early', `${s} data stops at ${h}:00 on ${date}; a full day runs to 23:00.`); });
  }

  // 5. Tables agree with each other: items in the orders table vs items in the category table.
  const itemsO = {}, itemsC = {};
  day.orders.forEach(r => { itemsO[r.store] = (itemsO[r.store] || 0) + r.items; });
  day.cats.forEach(r => { itemsC[r.store] = (itemsC[r.store] || 0) + r.items; });
  Object.keys(itemsO).forEach(s => {
    if (itemsC[s] == null) return; // already reported as missing
    const gap = Math.abs(itemsO[s] - itemsC[s]) / Math.max(itemsO[s], 1);
    if (gap > cfg.cross_table_tolerance) add(s, 'tables_disagree', `${s}: items in the orders table (${itemsO[s]}) and the category table (${itemsC[s]}) differ by ${(gap * 100).toFixed(1)}%.`);
  });
  return issues;
}

const DATA_CHECK_NAMES = ['every store reported in every table', 'no duplicate rows', 'no impossible values', 'data runs to the end of the day', 'orders and category tables agree'];

// Calculation checks for one finding. Returns [{ check, ok, detail }].
function calcChecks(f, tree, cityTotals, total) {
  const out = [];
  const rel = (a, b) => Math.abs(a - b) / Math.max(Math.abs(b), 1e-9);
  // 1. Each KPI equals the product of the KPIs under it, today and in the comparison weeks.
  const bad = [];
  Object.entries(tree).forEach(([p, kids]) => ['before', 'now'].forEach(w => {
    const prod = kids.reduce((a, k) => a * f.tree[k][w], 1);
    if (rel(prod, f.tree[p][w]) > 1e-6) bad.push(`${p} (${w}) is ${f.tree[p][w].toFixed(4)} but ${kids.join(' x ')} gives ${prod.toFixed(4)}`);
  }));
  out.push({ check: 'kpi_tree_multiplies_back', ok: !bad.length, detail: bad.length ? bad.join('; ') : 'each KPI equals the product of the KPIs under it' });
  // 2. Cities add up to the company total (only checked on company-wide findings).
  if (cityTotals && total) {
    const miss = ['sessions', 'orders', 'gmv'].filter(k => rel(cityTotals.reduce((a, c) => a + c[k], 0), total[k]) > 1e-9);
    out.push({ check: 'cities_add_to_total', ok: !miss.length, detail: miss.length ? `cities don't add up to the total for ${miss.join(', ')}` : 'cities add up to the company total' });
  }
  // 3. Mix and behaviour effects add up to each change.
  const off = f.drivers.filter(d => rel(d.mix_effect + d.rate_effect, d.change) > 1e-6 && Math.abs(d.change) > 1e-9);
  out.push({ check: 'mix_plus_behaviour_equals_change', ok: !off.length, detail: off.length ? `split by ${off.map(d => d.dim).join(', ')} doesn't add back up` : 'mix and behaviour effects add up to each change' });
  return out;
}


// ===== Detection, KPI tree and root cause (no AI) =====
// Metric Detective: data checks, anomaly detection, KPI-tree walk and root cause (mix vs behaviour)
// on daily data. No AI, no dependencies. The analyst-owned rules live in logic.js.

// In Node these come from the other files; inside the n8n Code node they are pasted in above this file.
function defaultLogic() { try { return LOGIC; } catch (e) { return require('./logic.js').LOGIC; } }
const CHK = (() => { try { return { dataChecks, calcChecks, DATA_CHECK_NAMES }; } catch (e) { return require('./checks.js'); } })();

const addDays = (s, n) => { const t = new Date(s + 'T00:00:00Z'); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };

function buildIndex(D, skipStores) {
  const skip = skipStores && skipStores.size ? skipStores : null;
  const byDate = {};
  const add = (date, key, row) => { if (skip && skip.has(row.store)) return; (byDate[date] = byDate[date] || { funnel: [], orders: [], cats: [] })[key].push(row); };
  D.funnel.forEach(r => add(r.date, 'funnel', r));
  D.orders.forEach(r => add(r.date, 'orders', r));
  D.cats.forEach(r => add(r.date, 'cats', r));
  return { byDate, dates: Object.keys(byDate).sort() };
}

const inScope = (r, scope) => !scope || ((!scope.city || r.city === scope.city) && (!scope.store || r.store === scope.store));

function totals(idx, dates, scope) {
  const t = { sessions: 0, checkouts: 0, pay_checkouts: 0, orders: 0, gmv: 0, items: 0 };
  for (const d of dates) {
    const b = idx.byDate[d];
    b.funnel.forEach(r => { if (inScope(r, scope)) { t.sessions += r.sessions; t.checkouts += r.checkouts; } });
    b.orders.forEach(r => { if (inScope(r, scope)) { t.pay_checkouts += r.checkouts; t.orders += r.orders; t.gmv += r.gmv; t.items += r.items; } });
  }
  const n = dates.length;
  Object.keys(t).forEach(k => { t[k] /= n; });
  t.aov = t.gmv / t.orders; t.conversion = t.orders / t.sessions; t.checkout_rate = t.checkouts / t.sessions;
  t.checkout_completion = t.orders / t.checkouts; // share of checkouts that became orders
  t.payment_success = t.orders / t.pay_checkouts; // per payment attempt (includes retries), so it is not a tree node
  t.items_per_order = t.items / t.orders; t.price_per_item = t.gmv / t.items;
  return t;
}

// Same weekday over the previous N weeks, by calendar date (a missing day can't shift the weekday).
function baselineDates(idx, date, weeks) {
  const out = [];
  for (let k = 1; k <= weeks; k++) { const d = addDays(date, -7 * k); if (idx.byDate[d]) out.push(d); }
  return out.length === weeks ? out : null;
}

function median(a) { const s = a.slice().sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; }

function check(idx, date, base, scope, level, L) {
  const now = totals(idx, [date], scope);
  const hist = base.map(d => totals(idx, [d], scope));
  const out = [];
  for (const k of L.kpis.primary.concat(L.kpis.secondary)) {
    const vals = hist.map(h => h[k]);
    const med = median(vals);
    const mad = median(vals.map(v => Math.abs(v - med))) * 1.4826;
    const scale = Math.max(mad, L.noise_floor[level] * Math.abs(med));
    const pct = (now[k] - med) / med;
    const z = (now[k] - med) / scale;
    if (Math.abs(pct) >= L.thresholds[level] && Math.abs(z) >= L.z_min) out.push({ level, scope: scope || {}, kpi: k, primary: L.kpis.primary.includes(k), now: now[k], usual: med, pct, z });
  }
  return out;
}

function detect(idx, date, base, L) {
  const cityOf = {};
  idx.byDate[date].funnel.forEach(r => { cityOf[r.store] = r.city; });
  const cities = [...new Set(Object.values(cityOf))];
  let alerts = check(idx, date, base, null, 'total', L);
  cities.forEach(c => { alerts = alerts.concat(check(idx, date, base, { city: c }, 'city', L)); });
  Object.keys(cityOf).forEach(s => { alerts = alerts.concat(check(idx, date, base, { city: cityOf[s], store: s }, 'store', L)); });
  const event = (L.calendar || []).find(e => e.date === date);
  return { date, event: event ? event.name : null, alerts: event ? [] : alerts, suppressed: event ? alerts.length : 0 };
}

// Mix vs behaviour for a ratio metric R = sum(num) / sum(den) split by a dimension.
// change = mix_effect + rate_effect exactly; the calculation check verifies it.
function mixRate(rows0, rows1, dim, num, den, n0) {
  const seg = {};
  const put = (rows, which, div) => rows.forEach(r => {
    const k = r[dim]; seg[k] = seg[k] || { n0: 0, d0: 0, n1: 0, d1: 0 };
    seg[k][which === 0 ? 'n0' : 'n1'] += r[num] / div; seg[k][which === 0 ? 'd0' : 'd1'] += r[den] / div;
  });
  put(rows0, 0, n0); put(rows1, 1, 1);
  const D0 = Object.values(seg).reduce((a, s) => a + s.d0, 0), D1 = Object.values(seg).reduce((a, s) => a + s.d1, 0);
  const N0 = Object.values(seg).reduce((a, s) => a + s.n0, 0), N1 = Object.values(seg).reduce((a, s) => a + s.n1, 0);
  const R0 = N0 / D0, R1 = N1 / D1;
  let mix = 0, rate = 0;
  const segs = Object.entries(seg).map(([k, s]) => {
    const w0 = s.d0 / D0, w1 = s.d1 / D1, r0 = s.d0 ? s.n0 / s.d0 : 0, r1 = s.d1 ? s.n1 / s.d1 : 0;
    const m = (w1 - w0) * (r0 - R0), rt = w1 * (r1 - r0);
    mix += (w1 - w0) * r0; rate += rt;
    return { segment: k, share_before: w0, share_now: w1, rate_before: r0, rate_now: r1, mix_effect: m, rate_effect: rt };
  });
  segs.sort((a, b) => Math.abs(b.rate_effect) + Math.abs(b.mix_effect) - Math.abs(a.rate_effect) - Math.abs(a.mix_effect));
  const totalAbsRate = segs.reduce((a, x) => a + Math.abs(x.rate_effect), 0) || 1;
  return { dim, before: R0, now: R1, change: R1 - R0, mix_effect: mix, rate_effect: rate, concentration: Math.abs(segs[0].rate_effect) / totalAbsRate, segments: segs.length, top: segs.slice(0, 3) };
}

function rowsFor(idx, dates, scope, key) {
  let out = [];
  dates.forEach(d => { out = out.concat(idx.byDate[d][key].filter(r => inScope(r, scope))); });
  return out;
}

// Join funnel + orders at store x user_type so conversion can be split by user type, city or store.
function userRows(idx, dates, scope) {
  const m = {};
  rowsFor(idx, dates, scope, 'funnel').forEach(r => { const k = r.date + r.store + r.user_type; m[k] = Object.assign({ orders: 0, gmv: 0, items: 0 }, r); });
  rowsFor(idx, dates, scope, 'orders').forEach(r => { const k = r.date + r.store + r.user_type; m[k].orders += r.orders; m[k].gmv += r.gmv; m[k].items += r.items; });
  return Object.values(m);
}

// Walk the KPI tree from the primary KPI: at every node, how much of the move each child explains.
function treeWalk(t, kpiTree, root) {
  const steps = [];
  const queue = [root];
  while (queue.length) {
    const p = queue.shift();
    const kids = kpiTree[p];
    if (!kids) continue;
    const lp = Math.log(t[p].now / t[p].before);
    const parts = kids.map(k => ({ kpi: k, change: t[k].now / t[k].before - 1, log: Math.log(t[k].now / t[k].before) }));
    const main = parts.slice().sort((a, b) => Math.abs(b.log) - Math.abs(a.log))[0].kpi;
    steps.push({ kpi: p, change: t[p].now / t[p].before - 1, log: lp, parts, main });
    kids.forEach(k => queue.push(k));
  }
  const path = [root];
  let cur = root;
  while (kpiTree[cur]) { cur = steps.find(s => s.kpi === cur).main; path.push(cur); }
  return { steps, path };
}

function explain(idx, date, base, alerts, L) {
  const alert = alerts[0];
  const scope = alert.scope && alert.scope.city ? alert.scope : null;
  const b = totals(idx, base, scope), n = totals(idx, [date], scope);
  const tree = {};
  ['gmv', 'orders', 'aov', 'sessions', 'conversion', 'checkout_rate', 'checkout_completion', 'payment_success', 'items_per_order', 'price_per_item']
    .forEach(k => { tree[k] = { before: b[k], now: n[k] }; });
  const u0 = userRows(idx, base, scope), u1 = userRows(idx, [date], scope);
  const p0 = rowsFor(idx, base, scope, 'orders'), p1 = rowsFor(idx, [date], scope, 'orders');
  const dims = [
    mixRate(u0, u1, 'user_type', 'orders', 'sessions', base.length),
    mixRate(p0, p1, 'payment', 'orders', 'checkouts', base.length),
    mixRate(u0, u1, 'user_type', 'gmv', 'orders', base.length)
  ];
  dims[0].metric = 'conversion'; dims[1].metric = 'payment_success'; dims[2].metric = 'aov';
  if (!scope || !scope.store) {
    const geo = scope ? 'store' : 'city';
    const a = mixRate(u0, u1, geo, 'orders', 'sessions', base.length); a.metric = 'conversion'; dims.push(a);
    const c = mixRate(u0, u1, geo, 'gmv', 'orders', base.length); c.metric = 'aov'; dims.push(c);
    const pg = mixRate(p0.filter(r => r.payment === 'UPI'), p1.filter(r => r.payment === 'UPI'), geo, 'orders', 'checkouts', base.length); pg.metric = 'upi_success'; dims.push(pg);
  }
  const c0 = rowsFor(idx, base, scope, 'cats'), c1 = rowsFor(idx, [date], scope, 'cats');
  const cat = {};
  c0.forEach(r => { cat[r.category] = cat[r.category] || { items_before: 0, items_now: 0, stockout_hours_now: 0 }; cat[r.category].items_before += r.items / base.length; });
  c1.forEach(r => { cat[r.category] = cat[r.category] || { items_before: 0, items_now: 0, stockout_hours_now: 0 }; cat[r.category].items_now += r.items; cat[r.category].stockout_hours_now += r.stockout_hours; });
  const categories = Object.entries(cat).map(([k, v]) => ({ category: k, items_before: v.items_before, items_now: v.items_now, change: v.items_now / v.items_before - 1, stockout_hours_now: v.stockout_hours_now }))
    .sort((x, y) => Math.abs(y.change) - Math.abs(x.change)).slice(0, 3);
  // Verdict per ratio metric that alerted: moved by mix (who showed up) or by behaviour (what they did)?
  const verdicts = {};
  alerts.filter(a => ['aov', 'conversion'].includes(a.kpi)).forEach(a => {
    const userSplit = dims.find(d => d.metric === a.kpi && d.dim === 'user_type');
    verdicts[a.kpi] = userSplit && Math.abs(userSplit.mix_effect) > 2 * Math.abs(userSplit.rate_effect) ? 'mix_shift' : 'behaviour_change';
  });
  const f = { date, scope: alert.scope, alerts: alerts.map(a => ({ kpi: a.kpi, primary: a.primary, now: a.now, usual: a.usual, pct: a.pct })), baseline_days: base, tree, drivers: dims, categories, verdicts };
  f.kpi_walk = treeWalk(tree, L.kpi_tree, L.kpis.primary[0]);
  // Calculation checks: the numbers must add back up before anyone sees them.
  let cityTotals = null, total = null;
  if (!scope) {
    const cities = [...new Set(idx.byDate[date].funnel.map(r => r.city))];
    cityTotals = cities.map(c => totals(idx, [date], { city: c }));
    total = n;
  }
  f.calc_checks = CHK.calcChecks(f, L.kpi_tree, cityTotals, total);
  f.calc_ok = f.calc_checks.every(c => c.ok);
  return f;
}

// Cache the raw index per dataset, so a 90-day replay doesn't rebuild it every day.
const RAW = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
function rawIndex(D) {
  if (RAW && RAW.has(D)) return RAW.get(D);
  const idx = buildIndex(D);
  if (RAW) RAW.set(D, idx);
  return idx;
}

// One run: check the data, set aside bad stores, detect, walk the KPI tree, explain, check the maths.
function run(D, date, logic) {
  const L = logic || defaultLogic();
  const raw = rawIndex(D);
  const cfg = L.data_checks || {};
  const checksOn = cfg.enabled !== false;
  const empty = { date, event: null, suppressed_alerts: 0, alert_count: 0, alerts: [], findings: [] };

  // 1. Data checks on today and on every comparison day.
  if (!raw.byDate[date]) return Object.assign(empty, { data: { status: 'no_data', issues: [{ date, store: '*', check: 'missing_day', detail: `No data at all for ${date}.` }], set_aside: [], stores_checked: 0, checks: CHK.DATA_CHECK_NAMES } });
  const base = baselineDates(raw, date, L.baseline_weeks);
  if (!base) return Object.assign(empty, { data: { status: 'no_baseline', issues: [], set_aside: [], stores_checked: 0, checks: CHK.DATA_CHECK_NAMES } });
  const master = [...new Set(base.concat([date]).flatMap(d => raw.byDate[d].funnel.map(r => r.store)))];
  const issues = checksOn ? base.concat([date]).flatMap(d => CHK.dataChecks(raw.byDate[d], d, master, cfg)) : [];
  if (issues.some(i => i.store === '*')) return Object.assign(empty, { data: { status: 'no_data', issues, set_aside: [], stores_checked: master.length, checks: CHK.DATA_CHECK_NAMES } });
  const setAside = new Set(issues.map(i => i.store));
  const data = { status: setAside.size ? 'stores_set_aside' : 'ok', issues, set_aside: [...setAside], stores_checked: master.length, checks: CHK.DATA_CHECK_NAMES };
  if (setAside.size / master.length > (cfg.max_stores_set_aside || 0.25)) return Object.assign(empty, { data: Object.assign(data, { status: 'too_much_bad_data' }) });

  // 2. Compare like with like: bad stores are left out of today AND the comparison weeks.
  const idx = setAside.size ? buildIndex(D, setAside) : raw;
  const det = detect(idx, date, base, L);
  const rank = { total: 0, city: 1, store: 2 };
  const scopeKey = a => (a.scope.city || 'all') + '/' + (a.scope.store || '');
  const seen = {};
  const picked = [];
  det.alerts.sort((a, b) => rank[a.level] - rank[b.level] || (b.primary - a.primary) || Math.abs(b.z) - Math.abs(a.z)).forEach(a => {
    const k = scopeKey(a);
    const coveredByCity = a.level === 'store' && seen[a.scope.city + '/'];
    const coveredByTotal = a.level !== 'total' && seen['all/'];
    if (seen[k] || coveredByCity || coveredByTotal) return;
    seen[k] = true; picked.push(a);
  });
  const allFor = a => det.alerts.filter(x => scopeKey(x) === scopeKey(a)).sort((p, q) => (q.primary - p.primary) || Math.abs(q.z) - Math.abs(p.z));
  const findings = picked.map(a => {
    const f = explain(idx, date, base, allFor(a), L);
    f.level = a.level;
    f.stores_also_alerting = [...new Set(det.alerts.filter(x => x.level === 'store' && (a.level === 'total' || x.scope.city === a.scope.city)).map(x => x.scope.store))];
    return f;
  });
  return { date, event: det.event, suppressed_alerts: det.suppressed, alert_count: det.alerts.length, alerts: det.alerts.map(a => ({ level: a.level, scope: a.scope, kpi: a.kpi, pct: a.pct })), findings, data, stores_analysed: master.length - setAside.size };
}


// ===== Fact lines for the write-up =====
// Turns a run result into plain-English fact lines with fixed, pre-formatted numbers.
// The AI may only use these numbers; the checker compares against them.

const pct = x => (x * 100).toFixed(1) + '%';
const chg = x => (x >= 0 ? '+' : '') + (x * 100).toFixed(1) + '%';
const inr = x => 'Rs ' + Math.round(x).toLocaleString('en-IN');
const n0 = x => Math.round(x).toLocaleString('en-IN');
const NAMES = { gmv: 'GMV', orders: 'orders', aov: 'average order value', sessions: 'app sessions', conversion: 'conversion (orders per session)' };
const TREE_NAMES = { gmv: 'GMV', orders: 'orders', aov: 'average order value', sessions: 'sessions', conversion: 'conversion', checkout_rate: 'checkout rate', checkout_completion: 'checkout completion (checkouts that became orders)', items_per_order: 'items per order', price_per_item: 'price per item' };
const fmtKpi = (k, v) => k === 'gmv' || k === 'aov' ? inr(v) : (k === 'conversion' ? pct(v) : n0(v));
const DIM = { user_type: 'user type', payment: 'payment method', city: 'city', store: 'store' };
const METRIC = { conversion: 'conversion', payment_success: 'payment success rate', aov: 'average order value', upi_success: 'UPI payment success rate' };
const fmtRate = (m, v) => m === 'aov' ? inr(v) : pct(v);

function dataLines(result) {
  const d = result.data;
  if (!d || d.status === 'no_baseline') return [];
  if (d.status === 'ok') return [`Data checks passed for ${result.date}: all ${d.stores_checked} stores, on today and the 4 comparison days (${d.checks.join('; ')}).`];
  const groups = {}, out = [];
  d.issues.forEach(i => {
    // A duplicate load also makes the tables disagree; report the cause, not the symptom.
    if (i.check === 'tables_disagree' && d.issues.some(j => j.store === i.store && j.date === i.date && j.check === 'duplicate_rows')) return;
    const k = i.date + '|' + i.store + '|' + i.check;
    (groups[k] = groups[k] || []).push(i);
  });
  Object.values(groups).forEach(g => {
    const i = g[0];
    const detail = i.check === 'duplicate_rows' && g.length > 1
      ? `${i.store} has duplicate rows (the same data loaded twice): ${g.map(x => x.detail.match(/has (\d+) duplicate rows in the (\w+) table/)).map(m => m[1] + ' in the ' + m[2] + ' table').join(', ')}.`
      : g.map(x => x.detail).join(' ');
    out.push(`DATA PROBLEM${i.date !== result.date ? ` (on ${i.date}, one of the comparison days)` : ''}: ${detail}`);
  });
  if (d.status === 'no_data') out.push('No analysis today: there is no data to analyse.');
  else if (d.status === 'too_much_bad_data') out.push(`No analysis today: ${d.set_aside.length} of ${d.stores_checked} stores failed a data check, too many for a fair comparison.`);
  else out.push(`Set aside: ${d.set_aside.join(', ')}. Left out of today and the comparison days, so the other ${d.stores_checked - d.set_aside.length} stores are compared like for like.`);
  return out;
}

function facts(result, logic) {
  const lines = dataLines(result);
  if (result.event) lines.push(`Known event today: ${result.event}. ${result.suppressed_alerts} alerts were suppressed because the business calendar expects unusual numbers.`);
  result.findings.forEach((f, i) => {
    const where = f.scope.store ? `${f.scope.store} store (${f.scope.city})` : (f.scope.city ? f.scope.city : 'all cities');
    lines.push(`FINDING ${i + 1}: ${where}, ${result.date}, compared with the average of the same weekday over the previous 4 weeks.`);
    const t = f.tree;
    f.alerts.forEach(a => { const u = t[a.kpi].before, v = t[a.kpi].now; lines.push(`- ${NAMES[a.kpi]}: usual ${fmtKpi(a.kpi, u)}, today ${fmtKpi(a.kpi, v)} (${chg(v / u - 1)}).`); });
    lines.push(`- Funnel, usual vs today: app sessions ${n0(t.sessions.before)} vs ${n0(t.sessions.now)}; checkout rate ${pct(t.checkout_rate.before)} vs ${pct(t.checkout_rate.now)}; payment success ${pct(t.payment_success.before)} vs ${pct(t.payment_success.now)}; items per order ${t.items_per_order.before.toFixed(2)} vs ${t.items_per_order.now.toFixed(2)}.`);
    f.drivers.forEach(d => {
      const big = Math.abs(d.rate_effect) + Math.abs(d.mix_effect);
      const rel = big / (d.metric === 'aov' ? d.before : Math.max(d.before, 1e-9));
      if (rel < 0.02) return;
      if (['city', 'store'].includes(d.dim) && d.concentration < 0.5) return; // spread evenly across places: not a local cause
      const s = d.top[0];
      const kind = Math.abs(d.mix_effect) > 2 * Math.abs(d.rate_effect) ? 'MIX (the share of each group changed, not their behaviour)' : 'BEHAVIOUR (a group behaved differently)';
      lines.push(`- ${METRIC[d.metric]} by ${DIM[d.dim]}: overall ${fmtRate(d.metric, d.before)} -> ${fmtRate(d.metric, d.now)}; driver type ${kind}. Biggest segment: ${s.segment}, ${fmtRate(d.metric, s.rate_before)} -> ${fmtRate(d.metric, s.rate_now)}, share ${pct(s.share_before)} -> ${pct(s.share_now)}.`);
    });
    const itemsChange = (t.orders.now * t.items_per_order.now) / (t.orders.before * t.items_per_order.before) - 1;
    f.categories.filter(c => Math.abs((1 + c.change) / (1 + itemsChange) - 1) >= 0.15 || c.stockout_hours_now >= 6).forEach(c =>
      lines.push(`- Category ${c.category}: items ${n0(c.items_before)} usual vs ${n0(c.items_now)} today (${chg(c.change)}); out-of-stock hours today across stores ${c.stockout_hours_now}.`));
    Object.entries(f.verdicts || {}).forEach(([k, v]) => lines.push(`- Verdict for ${NAMES[k]}: ${v === 'mix_shift' ? 'MIX SHIFT. Each user group behaved normally; the drop comes from more low-spend or low-converting users in the mix. Not a problem in itself.' : 'BEHAVIOUR CHANGE. Something changed for a specific group.'}`));
    const st = f.stores_also_alerting;
    if (st.length) lines.push(st.length > 5 ? `- ${st.length} of 20 stores also moved beyond their own thresholds.` : `- Stores also alerting: ${st.join(', ')}.`);
    // KPI tree walk, from the primary KPI down.
    if (f.kpi_walk) {
      f.kpi_walk.steps.forEach(stp => lines.push(`- KPI tree: ${TREE_NAMES[stp.kpi]} ${chg(stp.change)} = ${stp.parts.map(p => `${TREE_NAMES[p.kpi]} ${chg(p.change)}`).join(' x ')}. Bigger mover: ${TREE_NAMES[stp.main]}.`));
      lines.push(`- Main path down the KPI tree: ${f.kpi_walk.path.map(k => TREE_NAMES[k]).join(' -> ')}.`);
    }
    // Calculation checks.
    if (f.calc_checks) {
      const failed = f.calc_checks.filter(c => !c.ok);
      lines.push(failed.length ? `- CALCULATION CHECK FAILED: ${failed.map(c => c.detail).join('; ')}.` : `- Calculation checks passed: ${f.calc_checks.map(c => c.detail).join('; ')}.`);
    }
    // Analyst context that applies to this finding.
    const L = logic || defaultLogic();
    const tags = new Set(f.alerts.map(a => a.kpi));
    f.drivers.forEach(dd => { tags.add(dd.metric); tags.add(dd.dim); });
    const allItems = (t.orders.now * t.items_per_order.now) / (t.orders.before * t.items_per_order.before) - 1;
    f.categories.filter(c => Math.abs((1 + c.change) / (1 + allItems) - 1) >= 0.15 || c.stockout_hours_now >= 6).forEach(c => tags.add(c.category));
    (L.context || []).filter(c => c.tags.some(t => tags.has(t) && relevant(t, f))).forEach(c => lines.push(`- Analyst context: ${c.note}`));
  });
  return lines;
}

function defaultLogic() { try { return LOGIC; } catch (e) { return require('./logic.js').LOGIC; } }

// A context note only applies if its tag is part of what actually moved.
function relevant(tag, f) {
  if (tag === 'upi_success' || tag === 'payment') return f.drivers.some(d => (d.metric === 'upi_success' || d.metric === 'payment_success') && Math.abs(d.change) / Math.max(d.before, 1e-9) >= 0.02);
  if (tag === 'user_type') return Object.values(f.verdicts || {}).includes('mix_shift');
  return true;
}

// Days with no business finding but a data problem get a fixed email: no AI, no cost.
function templateEmail(result) {
  const d = result.data || {};
  const issues = dataLines(result);
  if (d.status === 'no_data' || d.status === 'too_much_bad_data')
    return { subject: `Data problem: no analysis for ${result.date}`, body: issues.join('\n') + '\n\nFix the data pipeline, then re-run. No business conclusions were drawn.' };
  if (result.findings.length && result.findings.some(f => !f.calc_ok))
    return { subject: `Alert held back: a calculation check failed on ${result.date}`, body: facts(result).filter(l => /CALCULATION|DATA PROBLEM/.test(l)).join('\n') + '\n\nThe numbers did not add back up, so no explanation was sent. Check the KPI tree in logic.js.' };
  if (!result.findings.length && d.status === 'stores_set_aside' && d.issues.some(i => i.date === result.date))
    return { subject: `Data problem, no business alerts: ${d.set_aside.join(', ')} set aside on ${result.date}`, body: issues.join('\n') + `\n\nThe other ${d.stores_checked - d.set_aside.length} stores look normal. Ask the data team to reload ${d.set_aside.join(', ')} before anyone reads that store's numbers.` };
  return null; // either nothing to say, or a business alert that the AI writes up
}

const needsAI = result => result.findings.length > 0 && result.findings.every(f => f.calc_ok);

// Numbers allowed in the email = numbers in the fact lines (plus the date parts).
function numbersIn(s) {
  return (String(s).replace(/(\d),(?=\d)/g, '$1').match(/\d+(?:\.\d+)?/g) || []);
}

function checkNumbers(text, factLines) {
  const allowed = new Set(numbersIn(factLines.join(' ')));
  const bad = numbersIn(text).filter(n => !allowed.has(n));
  return { ok: bad.length === 0, bad: [...new Set(bad)] };
}


